SELECT id, parent_id, name, sort_order, created_by, created_time, updated_by, updated_time, is_deleted, deleted_time FROM product_categories WHERE is_deleted = 0
AND parent_id = #{query.parentId}
AND name LIKE CONCAT('%', #{query.name}, '%')
ORDER BY ${query.sortField} ${query.sortOrder}
ORDER BY sort_order DESC, updated_time DESC

SELECT id AS categoryId, name AS categoryName, sort_order FROM product_categories WHERE is_deleted = 0 AND id IN
#{categoryId}
ORDER BY sort_order DESC
